        ignore_set.insert("myVar".to_string());

        let engine = UnsetVariablesEngine {
            _config: rule_config,
            ignore_set,
        };

        let ctx = FileContext {
            tree: &tree,
            source,
            file_path: std::path::Path::new("test.m"),
