//!     y = 'unterminated;   % STRIN
//! ```
//!
//! ### Correct
//!
//! ```matlab
//! x = 1 ~= 2;
//! a = 1; b = 2;
//! if x > 0
//!     y = 'terminated';
//! end
//! ```
//!
//! ### Fixed
//!
//! ```diff
//! - x = 1 != 2;
//! + x = 1 ~= 2;
//! - a = 1 b = 2;
//! + a = 1; b = 2;
//! ```
//!
//! ## Configuration
//!
//! ```toml
//! [lint.rules.SYNTAX_ERRORS_ENGINE]
//! disabled_checks = []
//! ```

